// Не spec (нет .e2e) — wdio его не запускает. helpers/* не меняем: здесь только композиция их функций.
import { $, driver, expect } from '@wdio/globals';
import { byText, byTextContains, byLabel, byLabelStartsWith, tapText, allByText } from '../../helpers/ui.ts';
import { goTab, hasDeepLinks, openRoute } from '../../helpers/nav.ts';

export type Nusach = 'אשכנזי' | 'ספרדי';

/** Видим ли элемент (без исключения, если его нет). */
export async function shown(el: ReturnType<typeof byText>) {
  return el.isDisplayed().catch(() => false);
}

/** Заголовок экрана молитвы/ברכה содержит «(אשכנזי)» / «(ספרדי)» (S-17 AC7).
 *  iOS (калибровка 11.10.2026, iPhone): заголовок — кнопка с label «בחירת נוסח. הנוסח המוצג: X», текст внутри не читается. */
export function nusachHeader(n: Nusach) {
  return driver.isAndroid
    ? byTextContains(`(${n})`)
    : $(`-ios predicate string:label CONTAINS "(${n})" OR label CONTAINS "הנוסח המוצג: ${n}"`);
}

/**
 * Перевести открытую молитву/ברכה в нужный נוסח через меню «בחירת נוסח» (как в NS-02).
 * Если נוסח уже тот — ничего не делает. Диалог «להחליף את התפילה לנוסח X?» подтверждается «החלף».
 */
export async function ensureNusach(n: Nusach) {
  if (await shown(nusachHeader(n))) return;
  // 11.10.2026 на iPhone первое «החלף» иногда не срабатывает (окно закрывается, נוסח прежний) — до 2 попыток.
  for (let attempt = 0; attempt < 2; attempt++) {
    await (await byLabelStartsWith('בחירת נוסח')).click();
    await tapText(n);
    const replace = await byText('החלף');
    if (await replace.waitForDisplayed({ timeout: 5000 }).then(() => true).catch(() => false)) await replace.click();
    if (await (await nusachHeader(n)).waitForDisplayed({ timeout: 8000 }).then(() => true).catch(() => false)) return;
  }
  await expect(nusachHeader(n)).toBeDisplayed();
}

/** Кнопка плеера «השמע» / «השהה» (aria-label = accessibilityLabel; запасной путь — текст). */
export async function playerButton(name: 'השמע' | 'השהה') {
  const byLbl = await byLabel(name);
  if (await byLbl.isExisting().catch(() => false)) return byLbl;
  return byText(name);
}

/** Строка утверждённой записи под «השמע»: «הקראה: X · אושרה על ידי Y» (F-92 AC4). */
export function recordingLine() {
  return byTextContains('הקראה:');
}

/** Поле поиска на экранах списков (תהילים, ברכות) — единственное EditText/TextField экрана. */
export function searchField() {
  return driver.isAndroid
    ? $('android=new UiSelector().className("android.widget.EditText")')
    : $('-ios class chain:**/XCUIElementTypeTextField');
}
export async function typeSearch(text: string) {
  const f = await searchField();
  await f.waitForDisplayed({ timeout: 20000 });
  await f.clearValue();
  if (text) await f.setValue(text);
}

/** Открыть פרק תהילים: deep link, иначе «תהילים» → поиск по номеру → карточка с этим номером. */
export async function openTehilimChapter(num: number) {
  const title = `תהילים ${hebNum(num)}`;
  if (hasDeepLinks()) {
    await openRoute(`/tehilim/${num}`);
  } else {
    // ОБНОВЛЕНО 25.10: после #4cfbf19e (עבר QA 25.10) список глав — под вкладкой «ברכות» (корона); запасной путь — «תהילים».
    await goTab('ברכות');
    if (!(await byText('פרקי אבות').waitForExist({ timeout: 6000 }).then(() => true, () => false))) await goTab('תהילים');
    await typeSearch(String(num));
    await (await byText(hebNum(num))).click();
  }
  await (await byText(title)).waitForDisplayed({ timeout: 20000 });
}

/** Номер פרק буквами, как в списке и заголовке: 23 → «כ״ג», 1 → «א׳», 15 → «ט״ו», 120 → «ק״כ». */
export function hebNum(n: number): string {
  const ones = ['', 'א', 'ב', 'ג', 'ד', 'ה', 'ו', 'ז', 'ח', 'ט'];
  const tens = ['', 'י', 'כ', 'ל', 'מ', 'נ', 'ס', 'ע', 'פ', 'צ'];
  let s = n >= 100 ? 'ק' : '';
  const r = n % 100;
  if (r === 15) s += 'טו';
  else if (r === 16) s += 'טז';
  else s += tens[Math.floor(r / 10)] + ones[r % 10];
  return s.length === 1 ? `${s}׳` : `${s.slice(0, -1)}״${s.slice(-1)}`;
}

/** Пропустить тест с причиной в логе прогона (Mocha this.skip() причину не принимает). */
export function skipWith(ctx: Mocha.Context, reason: string): never {
  console.warn(`[skip] ${ctx.test?.title ?? ''}: ${reason}`);
  ctx.skip();
  throw new Error('unreachable');
}

/** Причина пропуска тестов озвучки без записи. */
export const NO_RECORDING = 'нет утверждённой записи — загрузить в /admin';

/** Прокрутить вверх (свайп вниз), пока элемент с точным текстом не станет видимым (до max свайпов). */
export async function scrollUpToText(text: string, max = 8) {
  for (let i = 0; i < max; i++) {
    const el = await byText(text);
    if (await el.isDisplayed().catch(() => false)) return el;
    const { width, height } = await driver.getWindowSize();
    await driver.action('pointer', { parameters: { pointerType: 'touch' } })
      .move({ x: Math.round(width / 2), y: Math.round(height * 0.3) })
      .down().pause(80)
      .move({ duration: 400, x: Math.round(width / 2), y: Math.round(height * 0.75) })
      .up().perform();
  }
  throw new Error(`Не найден текст после прокрутки вверх: ${text}`);
}

/**
 * Нажать элемент с точным текстом в средней части экрана — когда тот же текст есть в заголовке и в нижней навигации
 * (например «תהילים»: заголовок, переключатель «תהילים / פרקי אבות», вкладка).
 */
export async function tapTextInMiddle(text: string) {
  const { height } = await driver.getWindowSize();
  for (const el of await allByText(text)) {
    if (!(await el.isDisplayed().catch(() => false))) continue;
    const { y } = await el.getLocation();
    if (y > height * 0.07 && y < height * 0.85) { await el.click(); return; }
  }
  throw new Error(`Нет «${text}» в средней части экрана`);
}
